import{_ as t,o as a,c as n,a3 as i}from"./chunks/framework.BlfGB29P.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"ATLAS","text":"Modular Application Framework","tagline":"A modular TypeScript framework for reusable applications, plugins and Home-Assistant-oriented tools.","actions":[{"theme":"brand","text":"Architecture","link":"/en/projects/atlas/overview"},{"theme":"alt","text":"Development Status","link":"/en/projects/atlas/development-status"},{"theme":"alt","text":"Home Assistant","link":"/en/projects/atlas/homeassistant"},{"theme":"alt","text":"ATLAS Plugins","link":"/en/projects/atlas-plugins/"}]},"features":[{"icon":"modules","title":"Modular Architecture","details":"Clear separation between Core, Foundation, Runtime, Renderer, Home Assistant, Theme and Devtools."},{"icon":"gear","title":"Runtime Foundation","details":"Services, dependency injection, events and other runtime fundamentals."},{"icon":"plugin","title":"Plugin Ready","details":"ATLAS provides the platform; plugin authors have a dedicated ATLAS plugin documentation area."},{"icon":"home","title":"Close to Home Assistant","details":"Status panels, entity selection, HA card export and Lovelace resource checks are being expanded step by step."},{"icon":"test","title":"Testable","details":"Clear contracts, reference implementations and automated tests form the foundation."},{"icon":"package","title":"Monorepo","details":"Packages are managed through pnpm workspaces with clearly separated responsibilities."}]},"headers":[],"relativePath":"en/projects/atlas/index.md","filePath":"en/projects/atlas/index.md","lastUpdated":1793113714000}'),s={name:"en/projects/atlas/index.md"};function o(r,e,l,d,p,c){return a(),n("div",null,[...e[0]||(e[0]=[i('<h2 id="project-status" tabindex="-1">Project Status <a class="header-anchor" href="#project-status" aria-label="Permalink to &quot;Project Status&quot;">​</a></h2><p>ATLAS is currently in active development.</p><p>The current focus is the <strong>Home-Assistant-oriented ATLAS app</strong> with Administration, Plugin Hub, Card Editor and File Studio.</p><p>As of 2026-10-17: <strong>App 0.1.315</strong>, <strong>HACS integration 0.1.306</strong>. The Card Editor is the only integrated reference plugin. File Studio, Terminal, Icon Studio, Icon Library and Automation Exporter / Editor are maintained separately as external plugins. See <a href="./development-status">Development Status</a> for verified scope and open work.</p><p>Administration and Plugin Hub support German, English and French. Their saved language preference is shared across both surfaces, including when they run on separate app ports. A language parameter in a plugin URL still takes precedence.</p><div class="warning custom-block"><p class="custom-block-title">Development project</p><p>ATLAS is not released for production use yet. APIs, package structures and internal contracts may still change.</p></div><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal&quot;">​</a></h2><p>ATLAS is intended to become a shared technical foundation for several UGSo projects.</p><p>This includes:</p><ul><li>reusable services</li><li>EventBus</li><li>dependency injection</li><li>modular plugins</li><li>diagnostics and development tools</li><li>Home Assistant integrations</li><li>Administration and Plugin Hub</li><li>File Studio for approved Home Assistant file paths</li><li>Card Editor with a direct Expert workflow</li><li>shared theme and renderer structures</li></ul>',10)])])}const h=t(s,[["render",o]]);export{m as __pageData,h as default};
